  "adminApiKeys.docsBefore": "Stable v1 endpoints — full catalog at",
  "adminApiKeys.docsAfter": "Keys inherit the role you assigned and are scoped strictly to this tenant. Optionally restrict a key to specific reports — the shape a customer embedding one dashboard headlessly on their own site actually needs, instead of a tenant-wide credential. Revoke instantly from the list above.",
