  "releaseLog.v1_2_8.title": "AI governance fixes, mobile navigation & Ask Curf readability",
  "releaseLog.v1_2_8.c0": "Fixed PII scrubbing so it recurses into nested objects and arrays — REST data sources return rows in whatever shape the API gives them, and the redactor was previously only checking top-level string fields, so a credit card / Thai ID / SSN buried inside a nested object could slip through unmasked into the LLM prompt. Scope is unchanged: still CC / Thai ID / SSN only",
  "releaseLog.v1_2_8.c1": "Fixed a hallucination-checker false positive on AI-generated percentages — the number regex used a trailing word-boundary that doesn't match right after a `%` sign, so correct percentage figures were being flagged as unverifiable",
  "releaseLog.v1_2_8.c2": "Finished unifying the two multi-step agent code paths into one implementation (`lib/agent/runLoop.ts`), keeping the better behavior of each rather than running two divergent agents side by side",
  "releaseLog.v1_2_8.c3": "Causal driver output is now wired into Brief's narration, not just surfaced standalone",
  "releaseLog.v1_2_8.c4": "Fixed the sidebar drawer on small screens — it sized to its content instead of the viewport, so nav items past Decisions (Tables, Metrics, Agent, Marketplace, Admin, ...) were unreachable and couldn't be scrolled to",
  "releaseLog.v1_2_8.c5": "Fixed Ask Curf's workspace-wide answers rendering as one unreadable wall of text — the API already returned numbered \"here's what's missing\" answers with proper paragraph breaks, but the answer bubble had no whitespace CSS, so every line break was collapsed",

  "releaseLog.v1_2_6.title": "Predictive forecasting, decision outcomes, regional channels & security hardening",
  "releaseLog.v1_2_6.c0": "Watchers can now warn before a threshold is crossed, not just after — a new predictive mode projects the current trend forward",
  "releaseLog.v1_2_6.c1": "Every governed Metric forecasts its own next value, surfaced automatically in Ask Curf, Brief, and the Metrics page",
  "releaseLog.v1_2_6.c2": "Brief now narrates forward (\"on track to reach X by Y\"), not just what already happened",
  "releaseLog.v1_2_6.c3": "Decision Log rolls up win-rates by scenario, and surfaces a hint from similar past decisions before you commit to a new one",
  "releaseLog.v1_2_6.c4": "New Operate destination: LINE — push data straight to a LINE chat, alongside the existing Slack and webhook channels",
  "releaseLog.v1_2_6.c5": "API keys can now be scoped to specific reports with per-key usage metering, so embedded analytics can be sold as its own product",
  "releaseLog.v1_2_6.c6": "Fixed a cross-tenant data exposure risk in the Metric editor and encrypted REST connector credentials at rest (they were stored in plaintext)",
  "releaseLog.v1_2_6.c7": "Workspace templates now respect plan quotas for reports and watchers instead of bypassing them",
  "releaseLog.v1_2_6.c8": "SCIM directory sync is now correctly gated to the Business plan",
  "releaseLog.v1_2_6.c9": "Unified the public API's report-running path with the internal viewer — closes a rate-limit and run-history gap on the public API and adds the data-source visibility check to the internal viewer",
  "releaseLog.v1_2_6.c10": "Notebook AI autofill now shares the same safety controls (token budget, usage tracking, multi-provider support) as the rest of the platform",
  "releaseLog.v1_2_6.c11": "Fixed chart colors silently drifting from the active theme in a handful of block types",
  "releaseLog.v1_2_6.c12": "Fixed Story Mode showing the wrong currency and a non-functional \"Why\" button",
  "releaseLog.v1_2_6.c13": "Closed a SQL-guard gap that could let a crafted query smuggle a write statement past the read-only check",

  "releaseLog.v1_2_4.title": "Semantic Metric Layer, Cross-workspace Ask & Decision Log",
  "releaseLog.v1_2_4.c0": "One governed definition per business metric — Ask, Brief, and Watchers now read the same number instead of each re-deriving it from their own report SQL",
  "releaseLog.v1_2_4.c1": "Ask Curf across the whole workspace — ask a question without picking a report first",
  "releaseLog.v1_2_4.c2": "Workspace-configurable currency (previously hardcoded to USD everywhere)",
  "releaseLog.v1_2_4.c3": "Renamed \"Fast Brief\" to \"Brief\" in the sidebar",
  "releaseLog.v1_2_4.c4": "Log a decision against a governed metric — Curf re-checks it automatically and tells you whether it moved the number the way you expected",
  "releaseLog.v1_2_4.c5": "Entry points from the Metrics page and from Ask Curf's metric citations",
  "releaseLog.v1_2_4.c6": "Closes the Understand → Forecast → Act → Improve loop — the first feature that tracks whether a decision actually worked",

  "releaseLog.v1_2_3.title": "Trustworthy AI answers",
  "releaseLog.v1_2_3.c0": "When a question can't be answered from the data on hand, Curf now says exactly what data would be needed instead of guessing",

  "releaseLog.v1_2_2.title": "Public API & pilot rollout",
  "releaseLog.v1_2_2.c0": "/api/v1 now exposes dashboards, watchers, and ask-chat for external frontends",
  "releaseLog.v1_2_2.c1": "CORS support added to /api/v1 so external frontends can call the public API",
  "releaseLog.v1_2_2.c2": "Role-based login shipped for the Zero Dropout command-center pilot",

