  "forecast.triggerTitle": "Forecast — project future values",
  "forecast.title": "Forecast this chart",
  "forecast.description": "Draws a dashed line projecting where this metric is headed, based on its own history. Just for you — it doesn't change the saved report.",
  "forecast.howToPredict": "How should it predict?",
  "forecast.method.linear.label": "Linear",
  "forecast.method.linear.hint": "Fits one straight trend line through all the history.",
  "forecast.method.ets.label": "Smoothed",
  "forecast.method.ets.hint": "Weighs recent points more — reacts faster if the trend just changed.",
  "forecast.method.llm.label": "AI",
  "forecast.method.llm.hint": "Asks Curf AI to spot seasonality or turning points. A bit slower.",
  "forecast.howFarAhead": "How far ahead?",
  "forecast.periodsHint": "Projects {periods} {unit} past the last data point, based on how far apart the points already are.",
  "forecast.periodsHintPoint": "Number of future points to project — this chart's x-axis isn't a recognizable date pattern, so we can't tell you a real-world unit.",
  "forecast.unit.day.singular": "day",
  "forecast.unit.day.plural": "days",
  "forecast.unit.week.singular": "week",
  "forecast.unit.week.plural": "weeks",
  "forecast.unit.month.singular": "month",
  "forecast.unit.month.plural": "months",
  "forecast.unit.quarter.singular": "quarter",
  "forecast.unit.quarter.plural": "quarters",
  "forecast.unit.year.singular": "year",
  "forecast.unit.year.plural": "years",
  "forecast.unit.point.singular": "point",
  "forecast.unit.point.plural": "points",
  "forecast.chartLabel.linear": "Forecast →",
  "forecast.chartLabel.ets": "Smoothed forecast →",
  "forecast.chartLabel.llm": "AI forecast →",
  "forecast.accuracyBadge": "Curf has been {pct}% accurate over the last {n} predictions on this chart.",
  "forecast.rangeBetter": "Up to {value} ({pct})",
  "forecast.rangeWorse": "As low as {value} ({pct})",
  "forecast.methodologyToggle": "How is this range calculated?",
  "forecast.methodology.linear": "The range is ±1.96 standard deviations of how far actual values have historically strayed from a straight trend line — roughly a 95% band that stays the same width for every period ahead.",
  "forecast.methodology.ets": "The range is ±1.96 standard deviations of the weighted fit's error, and widens the further out you look — next period is more certain than six periods from now.",
  "forecast.methodology.llm": "The model picks the predicted values, but the confidence range itself reuses the straight-line trend's error margin — the model doesn't generate its own uncertainty estimate yet.",
  "forecast.methodology.why196": "1.96 isn't specific to Curf — it's the standard statistics constant for a 95% confidence interval: for normally-distributed data, 95% of values fall within ±1.96 standard deviations of the mean.",

